function resolveInspectorHeaderAlignment(
  section: BuilderSection,
  item: NonNullable<BuilderSection["layoutItems"]>[number],
  block: BuilderLayoutBlock,
): HeaderElementAlignment {
  const rowId = item.rowId ?? item.id;
  const rowItems = (section.layoutItems ?? []).filter(
    (candidate) => (candidate.rowId ?? candidate.id) === rowId,
  );
  return resolveHeaderElementAlignment(
    block,
    Math.max(0, rowItems.indexOf(item)),
    Math.max(1, rowItems.length),
  );
}

const getSupportedTypographyAreas = (
  kind: string,
  sectionId?: string,
): readonly TypographyArea[] => {
  const isHeader = sectionId === "header-document";
  if (kind === "heading") return ["title"] as const;
  if (kind === "text") return ["title", "body", "button", "eyebrow"] as const;
  if (kind === "button") return ["button"] as const;
  if (kind === "datePicker") return ["title", "body"] as const;
  if (kind === "list") return ["body"] as const;
  if (kind === "menu") return ["body"] as const;
  if (kind === "table") return ["body"] as const;
  if (kind === "image") return isHeader ? (["title"] as const) : ([] as const);
  if (
    kind === "icon" ||
    kind === "fluentForm" ||
    kind === "embed" ||
    kind === "breadcrumbs"
  ) {
    return [] as const;
  }
  if (isHeader) {
    if (kind === "headerCategories") return ["button"] as const;
    if (kind === "headerLanguage") return ["button"] as const;
    if (
      kind === "headerUtility" ||
      kind === "headerSearch" ||
      kind === "headerWishlist" ||
      kind === "headerCart" ||
      kind === "headerAccount" ||
      kind === "headerTheme"
    ) {
      return [] as const;
    }
    return ["title", "body", "button", "eyebrow"] as const;
  }
  return ["title", "body", "button", "eyebrow"] as const;
};

