// eslint-disable-next-line @typescript-eslint/no-explicit-any
type LooseHandler = (...args: any[]) => void;

function InspectorChoiceGroup<T extends string>({
  value,
  options,
  onChange,
}: {
  value: T;
  options: readonly { label: string; value: T }[];
  onChange: (value: T) => void;
}) {
  return (
    <div className="builder-inspector-choice-group">
      {options.map((option) => (
        <button
          key={option.value}
          type="button"
          className={option.value === value ? "is-active" : ""}
          onClick={() => onChange(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}

function getTypewriterPhraseSeed(text?: string) {
  const raw = text?.trim();
  if (!raw) return [""];

  const bracketStart = raw.indexOf("[");
  const bracketEnd = raw.indexOf("]");
  if (bracketStart !== -1 && bracketEnd > bracketStart) {
    const inner = raw.slice(bracketStart + 1, bracketEnd);
    const phrases = inner
      .split("|")
      .map((phrase) => phrase.trim())
      .filter(Boolean);
    if (phrases.length) return phrases;
  }

  return [raw];
}

function TypewriterPhrasesControl({
  block,
  fallbackText,
  onChange,
}: {
  block: BuilderLayoutBlock;
  fallbackText?: string;
  onChange: (phrases: string[]) => void;
}) {
  const phrases =
    block.typewriterPhrases && block.typewriterPhrases.length > 0
      ? block.typewriterPhrases
      : getTypewriterPhraseSeed(fallbackText);

  const updatePhrase = (phraseIndex: number, value: string) => {
    onChange(
      phrases.map((phrase, currentIndex) =>
        currentIndex === phraseIndex ? value : phrase,
      ),
    );
  };

  const addPhrase = () => {
    onChange([...phrases, ""]);
  };

  const removePhrase = (phraseIndex: number) => {
    const nextPhrases = phrases.filter((_, currentIndex) => currentIndex !== phraseIndex);
    onChange(nextPhrases.length > 0 ? nextPhrases : [""]);
  };

  return (
    <div className="builder-typewriter-lines">
      <div className="builder-card-title">
        <strong>Typewriter Lines</strong>
        <button
          type="button"
          className="builder-icon-button"
          onClick={addPhrase}
          aria-label="Add typewriter line"
          title="Add typewriter line"
        >
          <Plus size={14} />
        </button>
      </div>
      <div className="builder-typewriter-lines-list">
        {phrases.map((phrase, phraseIndex) => (
          <div className="builder-typewriter-line-row" key={phraseIndex}>
            <input
              value={phrase}
              onChange={(event) => updatePhrase(phraseIndex, event.target.value)}
              placeholder={`Line ${phraseIndex + 1}`}
            />
            <button
              type="button"
              className="builder-icon-button"
              onClick={() => removePhrase(phraseIndex)}
              aria-label={`Remove typewriter line ${phraseIndex + 1}`}
              title="Remove line"
            >
              <Trash2 size={14} />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

function InspectorPresetWithCustom({
  value,
  options,
  onChange,
  placeholder = "24",
}: {
  value?: string | null;
  options: readonly { label: string; value: string }[];
  onChange: (value: string | undefined) => void;
  placeholder?: string;
}) {
  const selectedValue = value ?? "";
  const selectedPreset = options.some(
    (option) => option.value === selectedValue,
  )
    ? selectedValue
    : "";
  const [isCustomDraft, setIsCustomDraft] = useState(false);
  const isCustom = isCustomDraft || selectedPreset === "";
  const customValue = selectedPreset ? "" : selectedValue;

  return (
    <div className="builder-preset-custom-control">
      <InspectorChoiceGroup
        value={isCustom ? "custom" : selectedPreset}
        options={[...options, { label: "Custom", value: "custom" }]}
        onChange={(nextValue) => {
          if (nextValue === "custom") {
            setIsCustomDraft(true);
            return;
          }
          setIsCustomDraft(false);
          onChange(nextValue);
        }}
      />
      {isCustom && (
        <div className="custom-spacing-input-wrapper builder-custom-size-input">
          <input
            type="text"
            inputMode="decimal"
            value={customValue}
            onChange={(event) => {
              const next = event.target.value.trim();
              onChange(next ? next : undefined);
            }}
            placeholder={placeholder}
          />
          <span>px/rem/clamp</span>
        </div>
      )}
    </div>
  );
}

const GRADIENT_PRESETS: Record<string, [string, string, string]> = {
  "indigo-purple": ["#a5b4fc", "#6366f1", "#a855f7"],
  "cyan-blue": ["#22d3ee", "#06b6d4", "#2563eb"],
  "emerald-teal": ["#34d399", "#10b981", "#0d9488"],
  "sunset-orange": ["#fb923c", "#f97316", "#ec4899"],
  "indigo-purple-cyan": ["#60a5fa", "#818cf8", "#c084fc"],
  "sunset-pink": ["#fb923c", "#ec4899", "#a855f7"],
  "gold-amber": ["#facc15", "#f59e0b", "#f97316"],
};

const getCustomGradientPatch = (
  block: any,
  presetField: "textGradientPreset" | "typewriterGradientPreset",
  change: Record<string, any>,
) => {
  const currentPreset = block[presetField] || "none";
  const patch: Record<string, any> = { ...change };

  if (currentPreset !== "none" && currentPreset !== "custom") {
    const colors = GRADIENT_PRESETS[currentPreset] || [
      "#ffffff",
      "#60a5fa",
      "#c084fc",
    ];

    patch[presetField] = "custom";
    if (change.textGradientCustomStart === undefined) {
      patch.textGradientCustomStart =
        block.textGradientCustomStart ?? colors[0];
    }
    if (change.textGradientCustomMiddle === undefined) {
      patch.textGradientCustomMiddle =
        block.textGradientCustomMiddle ?? colors[1];
    }
    if (change.textGradientCustomEnd === undefined) {
      patch.textGradientCustomEnd = block.textGradientCustomEnd ?? colors[2];
    }
    if (change.textGradientCustomStartOffset === undefined) {
      patch.textGradientCustomStartOffset =
        block.textGradientCustomStartOffset ?? 0;
    }
    if (change.textGradientCustomMiddleOffset === undefined) {
      patch.textGradientCustomMiddleOffset =
        block.textGradientCustomMiddleOffset ?? 50;
    }
    if (change.textGradientCustomEndOffset === undefined) {
      patch.textGradientCustomEndOffset =
        block.textGradientCustomEndOffset ?? 100;
    }
    if (change.textGradientCustomAngle === undefined) {
      patch.textGradientCustomAngle = block.textGradientCustomAngle ?? 135;
    }
  }

  return patch;
};

